/**
 * The DOM half of the working phones (Ruling MKT-8, MKT-9). `mountPhone(scr, opts)` makes one
 * look's `.scr` a working mini-store with plain event delegation: product pages, category
 * filters, a cart sheet, a menu, a search sheet and the demo checkout screen. No network.
 *
 * Markup contract (generated by scripts/looks/snapshot.mjs): product cards carry data-p-* (see phone-store.ts);
 * [data-cat] (+ optional data-facet) filter controls; [data-grid] marks the container whose cards
 * are filtered; [data-add], [data-bundle], [data-open-cart], [data-open-menu], [data-open-search],
 * [data-cart-total], [data-cart-label] are the look's own buttons and labels.
 *
 * Layers live inside the scroller (the look's CSS variables and classes only reach descendants of
 * `.scr`) as a zero-height sticky first child, so they stay put while the home scroll position is
 * preserved underneath. Motion is transform/opacity only, <= 280ms, none under reduced motion.
 */
import {
  cartCount,
  cartTotal,
  countLabel,
  defaultSelection,
  fmtEGP,
  FACTS,
  initialState,
  isFiltered,
  lineFor,
  optionGroups,
  productMatches,
  readProduct,
  reduce,
  searchProducts,
  type Action,
  type OptionGroup,
  type Product,
  type Selection,
  type State,
  type View,
} from './phone-store';

export type MountOptions = {
  /** Where the demo screen's button goes (the site's signup URL). */
  signupUrl: string;
};

const ESC_MAP: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};
const esc = (s: string) => s.replace(/[&<>"']/g, c => ESC_MAP[c]);

const ICON = {
  back: '<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 5l7 7-7 7"/></svg>',
  close:
    '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>',
  bag: '<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 8h12l-1 12H7z"/><path d="M9 8V7a3 3 0 016 0v1"/></svg>',
  check:
    '<svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>',
  plus: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>',
  minus:
    '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M5 12h14"/></svg>',
  search:
    '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="6.5"/><path d="M16 16l4.5 4.5"/></svg>',
};

const MOTION_MS = 280;
const reducedMotion = () =>
  typeof window !== 'undefined' &&
  typeof window.matchMedia === 'function' &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches;

type Shown = { view: View; el: HTMLElement; opener: Element | null };

export function mountPhone(scr: HTMLElement, opts: MountOptions): () => void {
  if (scr.dataset.psMounted) return () => {};
  scr.dataset.psMounted = '1';

  // ---- products (first card of an id wins; later cards only add photos) ----
  const products = new Map<string, Product>();
  const cards: { el: HTMLElement; id: string }[] = [];
  scr.querySelectorAll<HTMLElement>('[data-p-id]').forEach(el => {
    const p = readProduct({ ...el.dataset });
    if (!p) return;
    if (!products.has(p.id)) products.set(p.id, p);
    cards.push({ el, id: p.id });
  });

  let state: State = initialState();
  const shown: Shown[] = [];
  const cleanups: (() => void)[] = [];
  let toastTimer: ReturnType<typeof setTimeout> | undefined;
  const observers = new Map<HTMLElement, IntersectionObserver>();

  // ---- layer (sticky zero-height first child; --ps-h = the phone's visible height) ----
  const layer = document.createElement('div');
  layer.className = 'ps-layer';
  const root = document.createElement('div');
  root.className = 'ps-root';
  const live = document.createElement('div');
  live.className = 'ps-live';
  live.setAttribute('role', 'status');
  live.setAttribute('aria-live', 'polite');
  const toast = document.createElement('div');
  toast.className = 'ps-toast';
  toast.setAttribute('aria-hidden', 'true');
  root.append(live, toast);
  layer.appendChild(root);
  scr.insertBefore(layer, scr.firstChild);
  const setHeight = () => root.style.setProperty('--ps-h', `${scr.clientHeight}px`);
  setHeight();
  if (typeof ResizeObserver !== 'undefined') {
    const ro = new ResizeObserver(setHeight);
    ro.observe(scr);
    cleanups.push(() => ro.disconnect());
  }

  // ---- cards: one keyboard stop per product (the photo), cart badges ----
  for (const { el, id } of cards) {
    const hit = el.querySelector<HTMLElement>('.ph') ?? el;
    if (hit.getAttribute('role')) continue;
    hit.setAttribute('role', 'button');
    hit.tabIndex = 0;
    hit.setAttribute('aria-label', `عرض ${products.get(id)!.name}`);
    hit.dataset.psHit = id;
  }
  scr.querySelectorAll<HTMLElement>('[data-cat]').forEach(c => {
    c.setAttribute('role', 'button');
    c.setAttribute('aria-pressed', 'false');
  });
  const cartButtons = [...scr.querySelectorAll<HTMLElement>('.ib[data-open-cart]')];
  for (const b of cartButtons) {
    b.dataset.psLabel = b.getAttribute('aria-label') ?? 'السلة';
    const badge = document.createElement('span');
    badge.className = 'ps-badge';
    badge.setAttribute('aria-hidden', 'true');
    badge.hidden = true;
    b.appendChild(badge);
  }

  // ---- helpers ----
  const announce = (msg: string) => {
    live.textContent = ''; // cleared first so a repeated message is announced again
    setTimeout(() => (live.textContent = msg), 30);
  };
  const flash = (msg: string) => {
    toast.innerHTML = `<span>${esc(msg)}</span><button type="button" tabindex="-1" data-ps-act="cart">عرض السلة</button>`;
    toast.classList.add('is-on');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove('is-on'), 2600);
  };
  const dispatch = (a: Action) => {
    const prev = state;
    state = reduce(state, a);
    if (state !== prev) sync(prev);
  };
  const topShown = () => shown[shown.length - 1];
  const preferredDay = () => {
    const days = [...scr.querySelectorAll('.day')];
    const i = days.findIndex(d => d.classList.contains('on'));
    return i >= 0 ? i : undefined;
  };

  // ---- cart UI that lives in the look's own markup ----
  function syncCartUi() {
    const n = cartCount(state.cart);
    for (const b of cartButtons) {
      const badge = b.querySelector<HTMLElement>('.ps-badge')!;
      badge.hidden = n === 0;
      badge.textContent = n > 99 ? '99+' : String(n);
      b.setAttribute(
        'aria-label',
        n ? `${b.dataset.psLabel} (${n})` : (b.dataset.psLabel ?? 'السلة')
      );
    }
    root.querySelectorAll<HTMLElement>('.ps-cartbtn').forEach(b => {
      const badge = b.querySelector<HTMLElement>('.ps-badge');
      if (badge) {
        badge.hidden = n === 0;
        badge.textContent = n > 99 ? '99+' : String(n);
      }
    });
    scr
      .querySelectorAll<HTMLElement>('[data-cart-total]')
      .forEach(e => (e.textContent = fmtEGP(cartTotal(state.cart))));
    scr
      .querySelectorAll<HTMLElement>('[data-cart-label]')
      .forEach(e => (e.textContent = countLabel(n)));
  }

  // ---- filters ----
  const facetOf = (c: Element) => (c as HTMLElement).dataset.facet || 'cat';
  function groupHasAll(facet: string) {
    return [...scr.querySelectorAll<HTMLElement>('[data-cat="all"]')].some(
      c => facetOf(c) === facet
    );
  }
  function applyFilters() {
    const f = state.filters;
    const grids = [...scr.querySelectorAll<HTMLElement>('[data-grid]')];
    for (const g of grids) {
      let visible = 0;
      for (const { el, id } of cards) {
        if (!g.contains(el)) continue;
        const ok = productMatches(products.get(id)!, f);
        el.classList.toggle('ps-off', !ok);
        if (ok) visible++;
      }
      g.querySelectorAll(':scope > .ps-empty, :scope > .ps-fbar').forEach(n => n.remove());
      const active = [...scr.querySelectorAll<HTMLElement>('[data-cat].on')].filter(
        c => c.dataset.cat !== 'all' && !c.classList.contains('chip')
      );
      if (active.length && isFiltered(f)) {
        const bar = document.createElement('div');
        bar.className = 'ps-fbar';
        bar.innerHTML = `<span>${esc(active.map(c => (c.querySelector('h3,span') ?? c).textContent?.trim() ?? '').join(' · '))}</span><button type="button" data-ps-act="clear">اعرض الكل</button>`;
        g.prepend(bar);
      }
      if (visible === 0) {
        const empty = document.createElement('div');
        empty.className = 'ps-empty';
        empty.innerHTML = `<b>مفيش منتجات هنا دلوقتي</b><span>جرّب قسم تاني أو اعرض كل المنتجات.</span><button type="button" data-ps-act="clear">اعرض الكل</button>`;
        g.appendChild(empty);
      }
    }
    scr.querySelectorAll<HTMLElement>('[data-cat]').forEach(c => {
      const facet = facetOf(c);
      const v = f[facet] ?? 'all';
      const on = v === c.dataset.cat;
      c.classList.toggle('on', on);
      c.setAttribute('aria-pressed', String(on));
    });
  }
  function revealGrid() {
    const g = scr.querySelector<HTMLElement>('[data-grid]');
    if (!g) return;
    const top = g.getBoundingClientRect().top - scr.getBoundingClientRect().top;
    if (top > scr.clientHeight * 0.55 || top < 0)
      scr.scrollBy({ top: top - 76, behavior: reducedMotion() ? 'auto' : 'smooth' });
  }
  function onControl(c: HTMLElement) {
    const facet = facetOf(c);
    const v = c.dataset.cat ?? 'all';
    const turnOff = c.classList.contains('on') && v !== 'all' && !groupHasAll(facet);
    dispatch({ type: 'filter', facet, value: turnOff ? 'all' : v });
    applyFilters();
    revealGrid();
  }

  // ---- views ----
  function pdpHtml(p: Product): string {
    const groups = optionGroups(p);
    const sel = defaultSelection(p, preferredDay());
    const slides = (p.imgs.length ? p.imgs : [p.img])
      .map(
        (u, i) =>
          `<figure class="ps-slide"><img src="${esc(u)}" alt="${i === 0 ? esc(p.name) : ''}" ${i ? 'loading="lazy"' : ''} decoding="async" draggable="false"></figure>`
      )
      .join('');
    const dots =
      p.imgs.length > 1
        ? `<div class="ps-dots" aria-hidden="true">${p.imgs.map((_, i) => `<i${i ? '' : ' class="is-on"'}></i>`).join('')}</div>`
        : '';
    const save =
      p.old && p.old > p.price
        ? `<span class="ps-save">وفّر ${Math.round(((p.old - p.price) * 100) / p.old)}%</span>`
        : '';
    const groupHtml = groups.map(g => groupMarkup(g, sel)).join('');
    const specs = p.a.specs
      ? `<ul class="ps-specs">${p.a.specs
          .split('|')
          .map(s => `<li>${esc(s)}</li>`)
          .join('')}</ul>`
      : '';
    const facts = FACTS.filter(f => p.a[f.key])
      .map(f => `<div><dt>${f.label}</dt><dd>${esc(p.a[f.key])}</dd></div>`)
      .join('');
    return `<header class="ps-bar"><button type="button" class="ps-ibtn" data-ps-act="back" aria-label="رجوع">${ICON.back}</button><span class="ps-bar-t">${esc(p.name)}</span><button type="button" class="ps-ibtn ps-cartbtn" data-ps-act="cart" aria-label="السلة">${ICON.bag}<span class="ps-badge" aria-hidden="true" hidden></span></button></header>
<div class="ps-scroll"><div class="ps-gal" role="group" aria-label="صور المنتج" tabindex="0">${slides}</div>${dots}
<div class="ps-info"><h2 class="ps-title">${esc(p.name)}</h2>
<p class="ps-pricerow"><span class="ps-price">${fmtEGP(p.price)}</span>${p.old ? `<s class="ps-old">${fmtEGP(p.old)}</s>` : ''}${save}</p>
${p.a.desc ? `<p class="ps-desc">${esc(p.a.desc)}</p>` : ''}${specs}${groupHtml}
${facts ? `<dl class="ps-facts">${facts}</dl>` : ''}
<div class="ps-qrow"><span>الكمية</span>${stepper('pdp', 1)}</div></div></div>
<footer class="ps-foot"><button type="button" class="ps-cta" data-ps-act="add"><span>أضف للسلة</span><b data-ps-total>${fmtEGP(p.price)}</b></button></footer>`;
  }
  const stepper = (key: string, qty: number) =>
    `<div class="ps-qty" data-key="${esc(key)}"><button type="button" data-ps-act="dec" aria-label="قلّل الكمية">${ICON.minus}</button><output aria-live="off">${qty}</output><button type="button" data-ps-act="inc" aria-label="زوّد الكمية">${ICON.plus}</button></div>`;
  function groupMarkup(g: OptionGroup, sel: Selection): string {
    if (g.kind === 'chips')
      return `<fieldset class="ps-grp" data-group="${g.key}"><legend>${g.label}</legend><div class="ps-opts" role="radiogroup" aria-label="${g.label}">${g.values
        .map(
          v =>
            `<button type="button" role="radio" class="ps-chip${sel[g.key] === v.v ? ' is-on' : ''}" aria-checked="${sel[g.key] === v.v}" data-ps-act="opt" data-group="${g.key}" data-v="${esc(v.v)}">${esc(v.v)}</button>`
        )
        .join('')}</div></fieldset>`;
    if (g.kind === 'swatches')
      return `<fieldset class="ps-grp" data-group="${g.key}"><legend>${g.label}: <b class="ps-picked">${esc(sel[g.key] ?? '')}</b></legend><div class="ps-opts" role="radiogroup" aria-label="${g.label}">${g.values
        .map(
          v =>
            `<button type="button" role="radio" class="ps-sw${sel[g.key] === v.v ? ' is-on' : ''}" aria-checked="${sel[g.key] === v.v}" aria-label="${esc(v.v)}" style="--sw:${esc(v.hex ?? '#ccc')}" data-ps-act="opt" data-group="${g.key}" data-v="${esc(v.v)}"></button>`
        )
        .join('')}</div></fieldset>`;
    if (g.kind === 'check')
      return `<label class="ps-chk"><input type="checkbox" data-group="${g.key}" checked><span>${esc(g.text)}</span></label>`;
    return `<label class="ps-fld"><span>${esc(g.label)}</span><input type="text" class="ps-in" data-group="${g.key}" maxlength="${g.max}" autocomplete="off"></label>`;
  }
  function readSelection(el: HTMLElement, p: Product): Selection {
    const sel: Selection = {};
    for (const g of optionGroups(p)) {
      if (g.kind === 'chips' || g.kind === 'swatches') {
        sel[g.key] =
          el.querySelector<HTMLElement>(`[data-group="${g.key}"].is-on`)?.dataset.v ?? '';
      } else if (g.kind === 'check') {
        if (el.querySelector<HTMLInputElement>(`input[data-group="${g.key}"]`)?.checked)
          sel[g.key] = g.text.split(' (')[0];
      } else
        sel[g.key] =
          el.querySelector<HTMLInputElement>(`input[data-group="${g.key}"]`)?.value.trim() ?? '';
    }
    return sel;
  }
  const pdpQty = (el: HTMLElement) => Number(el.querySelector('.ps-qty output')?.textContent) || 1;
  function pdpTotal(el: HTMLElement, p: Product) {
    const t = el.querySelector('[data-ps-total]');
    if (t) t.textContent = fmtEGP(p.price * pdpQty(el));
  }

  function cartBody(): string {
    const cart = state.cart;
    if (!cart.length)
      return `<div class="ps-emptycart"><b>السلة فاضية</b><span>ضيف منتج من المتجر وهيظهر هنا.</span><button type="button" class="ps-ghost" data-ps-act="shop">كمّل التسوّق</button></div>`;
    const lines = cart
      .map(
        l => `<li class="ps-line" data-key="${esc(l.key)}"><div class="ps-lthumb">${l.img ? `<img src="${esc(l.img)}" alt="" width="64" height="64" loading="lazy" decoding="async">` : ''}</div>
<div class="ps-lbody"><b>${esc(l.name)}</b>${l.opts.length ? `<span class="ps-lopt">${esc(l.opts.join(' · '))}</span>` : ''}<span class="ps-lprice">${fmtEGP(l.price * l.qty)}</span></div>
${stepper(l.key, l.qty)}<button type="button" class="ps-rm" data-ps-act="rm" data-key="${esc(l.key)}" aria-label="شيل ${esc(l.name)} من السلة">${ICON.close}</button></li>`
      )
      .join('');
    return `<ul class="ps-lines">${lines}</ul><div class="ps-total"><span>الإجمالي</span><b>${fmtEGP(cartTotal(cart))}</b></div><p class="ps-note">الشحن بيتحسب في الخطوة الجاية.</p><button type="button" class="ps-cta" data-ps-act="checkout"><span>كمّل الطلب</span><b>${fmtEGP(cartTotal(cart))}</b></button>`;
  }
  const sheetHtml = (title: string, body: string) =>
    `<div class="ps-dim" data-ps-act="back"></div><section class="ps-sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><header class="ps-shead"><h2>${esc(title)}</h2><button type="button" class="ps-ibtn" data-ps-act="back" aria-label="إغلاق">${ICON.close}</button></header><div class="ps-sbody">${body}</div></section>`;

  function menuBody(): string {
    const seen = new Set<string>();
    const items: string[] = [`<li><button type="button" data-ps-act="home">الرئيسية</button></li>`];
    scr.querySelectorAll<HTMLElement>('[data-cat]').forEach(c => {
      const key = `${facetOf(c)}:${c.dataset.cat}`;
      if (c.dataset.cat === 'all' || seen.has(key)) return;
      seen.add(key);
      const label = (c.querySelector('h3,span') ?? c).textContent?.trim() ?? '';
      items.push(
        `<li><button type="button" data-ps-act="goto-cat" data-ps-facet="${esc(facetOf(c))}" data-ps-cat="${esc(c.dataset.cat ?? '')}">${esc(label)}</button></li>`
      );
    });
    items.push(
      `<li><button type="button" data-ps-act="cart">السلة${state.cart.length ? ` (${cartCount(state.cart)})` : ''}</button></li>`
    );
    return `<ul class="ps-menu">${items.join('')}</ul>`;
  }
  const searchBody = () =>
    `<label class="ps-fld ps-search"><span class="ps-sr">ابحث في المتجر</span><input type="search" class="ps-in" data-ps-search placeholder="ابحث عن منتج" autocomplete="off"></label><ul class="ps-results" data-ps-results></ul>`;

  const doneHtml = () => {
    const n = cartCount(state.cart);
    return `<header class="ps-bar"><button type="button" class="ps-ibtn" data-ps-act="back" aria-label="رجوع">${ICON.back}</button><span class="ps-bar-t">إتمام الطلب</span><span class="ps-ibtn" aria-hidden="true"></span></header>
<div class="ps-scroll"><div class="ps-donebody"><span class="ps-tick">${ICON.check}</span><h2>ده متجر تجريبي</h2><p class="ps-big">اعمل متجرك زيه، في دقايق.</p>
<p class="ps-desc">مفيش طلب اتبعت ولا فلوس اتسحبت. ده شكل متجرك لما يتفتح لعملائك.</p>
<div class="ps-sum"><span>${esc(countLabel(n).replace('في السلة', 'كانوا في طلبك'))}</span><b>${fmtEGP(cartTotal(state.cart))}</b></div>
<a class="ps-cta ps-signup" href="${esc(opts.signupUrl)}" target="_blank" rel="noopener noreferrer" data-ps-act="signup"><span>اعمل متجرك زيه</span><span class="sr-only"> (بيفتح في تبويب جديد)</span></a>
<button type="button" class="ps-ghost" data-ps-act="shop">كمّل التسوّق</button></div></div>`;
  };

  function createView(v: View): HTMLElement | null {
    const el = document.createElement('div');
    if (v.t === 'pdp') {
      const p = products.get(v.id);
      if (!p) return null;
      el.className = 'ps-view ps-page ps-pdp';
      el.setAttribute('role', 'dialog');
      el.setAttribute('aria-modal', 'true');
      el.setAttribute('aria-label', p.name);
      el.tabIndex = -1;
      el.dataset.id = p.id;
      el.innerHTML = pdpHtml(p);
      const gal = el.querySelector<HTMLElement>('.ps-gal');
      const dots = [...el.querySelectorAll('.ps-dots i')];
      if (gal && dots.length && typeof IntersectionObserver !== 'undefined') {
        const slides = [...gal.children];
        const io = new IntersectionObserver(
          es => {
            for (const e of es)
              if (e.isIntersecting && e.intersectionRatio > 0.6) {
                const i = slides.indexOf(e.target);
                dots.forEach((d, j) => d.classList.toggle('is-on', j === i));
              }
          },
          { root: gal, threshold: [0.6] }
        );
        slides.forEach(s => io.observe(s));
        observers.set(el, io);
      }
    } else if (v.t === 'done') {
      el.className = 'ps-view ps-page ps-done';
      el.setAttribute('role', 'dialog');
      el.setAttribute('aria-modal', 'true');
      el.setAttribute('aria-label', 'متجر تجريبي');
      el.tabIndex = -1;
      el.innerHTML = doneHtml();
    } else {
      el.className = `ps-view ps-sheetwrap ps-${v.t}`;
      el.innerHTML =
        v.t === 'cart'
          ? sheetHtml(`السلة${state.cart.length ? ` (${cartCount(state.cart)})` : ''}`, cartBody())
          : v.t === 'menu'
            ? sheetHtml('القائمة', menuBody())
            : sheetHtml('بحث', searchBody());
    }
    return el;
  }
  const focusTarget = (el: HTMLElement) => el.querySelector<HTMLElement>('.ps-sheet') ?? el;

  function openView(v: View, inherited?: Element | null) {
    const el = createView(v);
    if (!el) return;
    const opener = inherited ?? document.activeElement;
    root.appendChild(el);
    shown.push({ view: v, el, opener });
    void el.getBoundingClientRect(); // commit the start state, then transition to `is-in`
    el.classList.add('is-in');
    const f =
      v.t === 'search'
        ? (el.querySelector<HTMLElement>('input') ?? focusTarget(el))
        : focusTarget(el);
    f.focus({ preventScroll: true });
  }
  function closeView(s: Shown) {
    s.el.classList.remove('is-in');
    observers.get(s.el)?.disconnect();
    observers.delete(s.el);
    const drop = () => s.el.remove();
    if (reducedMotion()) drop();
    else {
      s.el.addEventListener('transitionend', e => e.target === s.el && drop(), { once: false });
      setTimeout(drop, MOTION_MS + 60);
    }
  }
  function updateInert() {
    const open = shown.length > 0;
    scr.classList.toggle('ps-lock', open);
    scr.classList.toggle(
      'ps-covered',
      shown.some(s => s.view.t === 'pdp' || s.view.t === 'done')
    );
    for (const ch of [...scr.children]) {
      if (ch === layer) continue;
      if (open) ch.setAttribute('inert', '');
      else ch.removeAttribute('inert');
    }
    shown.forEach((s, i) => {
      if (i < shown.length - 1) s.el.setAttribute('inert', '');
      else s.el.removeAttribute('inert');
    });
  }

  /** Brings the DOM in line with `state` (called after every dispatch that changed it). */
  function sync(prev: State) {
    // views: pop what left, push what arrived
    const want = state.stack;
    let i = 0;
    while (
      i < shown.length &&
      i < want.length &&
      JSON.stringify(shown[i].view) === JSON.stringify(want[i])
    )
      i++;
    const leaving = shown.splice(i);
    const firstOpener = leaving[0]?.opener ?? null;
    for (const s of leaving.reverse()) closeView(s);
    // the demo screen replaces the cart sheet: it inherits what the sheet would have returned focus to
    for (let j = i; j < want.length; j++) openView(want[j], j === i ? firstOpener : undefined);
    updateInert();
    if (state.stack.some(v => v.t === 'cart' || v.t === 'done')) toast.classList.remove('is-on');
    if (leaving.length && !shown.length) {
      const opener = firstOpener as HTMLElement | null;
      if (opener && opener.isConnected && typeof opener.focus === 'function')
        opener.focus({ preventScroll: true });
    } else if (leaving.length) {
      const top = topShown();
      if (top) focusTarget(top.el).focus({ preventScroll: true });
    }
    if (prev.cart !== state.cart) {
      syncCartUi();
      const cart = shown.find(s => s.view.t === 'cart');
      if (cart) refreshCartSheet(cart.el);
    }
  }
  function refreshCartSheet(el: HTMLElement) {
    const had = document.activeElement as HTMLElement | null;
    const act = had?.dataset?.psAct;
    const key = had?.closest<HTMLElement>('[data-key]')?.dataset.key;
    el.querySelector('h2')!.textContent =
      `السلة${state.cart.length ? ` (${cartCount(state.cart)})` : ''}`;
    el.querySelector('.ps-sbody')!.innerHTML = cartBody();
    const next = [...el.querySelectorAll<HTMLElement>('[data-ps-act]')].find(
      b =>
        b.dataset.psAct === act &&
        (b.dataset.key ?? b.closest<HTMLElement>('[data-key]')?.dataset.key) === key
    );
    (next ?? el.querySelector<HTMLElement>('.ps-sheet'))?.focus({ preventScroll: true });
  }

  // ---- adding ----
  function addProduct(p: Product, sel: Selection, qty: number) {
    dispatch({ type: 'add', line: lineFor(p, sel, qty) });
    announce('أضيف للسلة');
    flash('أضيف للسلة');
  }
  function quickAdd(id: string) {
    const p = products.get(id);
    if (!p) return;
    // a product that needs a size/colour choice opens its page; the rest go straight in
    if (p.a.sizes) dispatch({ type: 'open', view: { t: 'pdp', id } });
    else addProduct(p, defaultSelection(p, preferredDay()), 1);
  }

  // ---- events ----
  const onClick = (e: MouseEvent) => {
    const t = e.target as Element | null;
    if (!t || !t.closest) return;
    const inLayer = !!t.closest('.ps-layer');
    const act = t.closest<HTMLElement>('[data-ps-act]');
    if (act) {
      handleAct(act, e);
      return;
    }
    if (inLayer) {
      if (t.closest('a') && !t.closest('a[data-ps-act]')) e.preventDefault();
      return;
    }
    const add = t.closest<HTMLElement>('[data-add]');
    if (add) {
      const card = add.closest<HTMLElement>('[data-p-id]');
      if (card?.dataset.pId) quickAdd(card.dataset.pId);
      return;
    }
    const bundle = t.closest<HTMLElement>('[data-bundle]');
    if (bundle) {
      try {
        const items = JSON.parse(bundle.dataset.bundle ?? '[]') as {
          id: string;
          name: string;
          price: number;
          img: string;
        }[];
        for (const it of items) {
          const p = products.get(it.id);
          const sel = p ? defaultSelection(p) : {};
          dispatch({
            type: 'add',
            line: p
              ? lineFor(p, sel, 1)
              : {
                  key: it.id,
                  id: it.id,
                  name: it.name,
                  price: it.price,
                  img: it.img,
                  qty: 1,
                  opts: [],
                },
          });
        }
        announce('أضيف للسلة');
        flash('أضيف اللوك للسلة');
      } catch {
        /* a malformed bundle attribute does nothing */
      }
      return;
    }
    if (t.closest('[data-open-cart]')) return void dispatch({ type: 'open', view: { t: 'cart' } });
    if (t.closest('[data-open-menu]')) return void dispatch({ type: 'open', view: { t: 'menu' } });
    if (t.closest('[data-open-search]'))
      return void dispatch({ type: 'open', view: { t: 'search' } });
    const ctl = t.closest<HTMLElement>('[data-cat]');
    if (ctl) {
      e.preventDefault();
      return onControl(ctl);
    }
    const day = t.closest<HTMLElement>('.day');
    if (day) {
      day.parentElement?.querySelectorAll('.day').forEach(x => x.classList.remove('on'));
      day.classList.add('on');
      return;
    }
    const cmp = t.closest<HTMLElement>('.cmp');
    if (cmp) {
      cmp.setAttribute(
        'aria-pressed',
        cmp.getAttribute('aria-pressed') === 'true' ? 'false' : 'true'
      );
      return;
    }
    const chip = t.closest<HTMLElement>('.chip');
    if (chip) {
      chip.parentElement?.querySelectorAll('.chip').forEach(x => x.classList.remove('on'));
      chip.classList.add('on');
      return;
    }
    const card = t.closest<HTMLElement>('[data-p-id]');
    if (card?.dataset.pId && products.has(card.dataset.pId)) {
      dispatch({ type: 'open', view: { t: 'pdp', id: card.dataset.pId } });
      return;
    }
    if (t.closest('a')) e.preventDefault();
  };

  function handleAct(el: HTMLElement, e: Event) {
    const act = el.dataset.psAct;
    const view = el.closest<HTMLElement>('.ps-view');
    switch (act) {
      case 'back':
        return dispatch({ type: 'back' });
      case 'cart':
        return dispatch({ type: 'open', view: { t: 'cart' } });
      case 'home':
      case 'shop':
        dispatch({ type: 'closeAll' });
        if (act === 'home') scr.scrollTo({ top: 0, behavior: reducedMotion() ? 'auto' : 'smooth' });
        return;
      case 'clear':
        dispatch({ type: 'clearFilters' });
        return applyFilters();
      case 'goto-cat':
        dispatch({ type: 'closeAll' });
        dispatch({
          type: 'filter',
          facet: el.dataset.psFacet || 'cat',
          value: el.dataset.psCat ?? 'all',
        });
        applyFilters();
        return revealGrid();
      case 'opt': {
        const grp = el.closest('.ps-grp')!;
        grp.querySelectorAll('[data-ps-act="opt"]').forEach(b => {
          b.classList.toggle('is-on', b === el);
          b.setAttribute('aria-checked', String(b === el));
        });
        const picked = grp.querySelector('.ps-picked');
        if (picked) picked.textContent = el.dataset.v ?? '';
        return;
      }
      case 'inc':
      case 'dec': {
        const q = el.closest<HTMLElement>('.ps-qty')!;
        const key = q.dataset.key ?? '';
        if (key === 'pdp' && view) {
          const out = q.querySelector('output')!;
          out.textContent = String(
            Math.min(20, Math.max(1, (Number(out.textContent) || 1) + (act === 'inc' ? 1 : -1)))
          );
          const p = products.get(view.dataset.id ?? '');
          if (p) pdpTotal(view, p);
        } else {
          const line = state.cart.find(l => l.key === key);
          if (line) dispatch({ type: 'qty', key, qty: line.qty + (act === 'inc' ? 1 : -1) });
        }
        return;
      }
      case 'rm':
        return dispatch({ type: 'remove', key: el.dataset.key ?? '' });
      case 'add': {
        const p = products.get(view?.dataset.id ?? '');
        if (p && view) addProduct(p, readSelection(view, p), pdpQty(view));
        return;
      }
      case 'open-p':
        dispatch({ type: 'back' });
        return dispatch({ type: 'open', view: { t: 'pdp', id: el.dataset.id ?? '' } });
      case 'checkout':
        return dispatch({ type: 'checkout' });
      case 'signup':
        // a real link: opens the signup page in a new tab; nothing else in a phone navigates
        e.stopPropagation();
        return;
    }
  }

  const onInput = (e: Event) => {
    const input = e.target as HTMLInputElement;
    if (!input.matches?.('[data-ps-search]')) return;
    const list = input.closest('.ps-view')?.querySelector('[data-ps-results]');
    if (!list) return;
    const hits = searchProducts([...products.values()], input.value).slice(0, 8);
    list.innerHTML = hits.length
      ? hits
          .map(
            p =>
              `<li><button type="button" data-ps-act="open-p" data-id="${esc(p.id)}"><span class="ps-lthumb">${p.img ? `<img src="${esc(p.img)}" alt="" width="48" height="48" loading="lazy">` : ''}</span><span>${esc(p.name)}</span><b>${fmtEGP(p.price)}</b></button></li>`
          )
          .join('')
      : input.value.trim()
        ? '<li class="ps-nohit">مفيش نتيجة بالاسم ده.</li>'
        : '';
  };
  const onKey = (e: KeyboardEvent) => {
    if (e.key === 'Escape' && state.stack.length) {
      e.preventDefault();
      e.stopPropagation();
      dispatch({ type: 'back' });
      return;
    }
    // role=button stops made by the engine (photo, filter anchors) answer Enter/Space like buttons
    const t = e.target as HTMLElement;
    if (
      (e.key === 'Enter' || e.key === ' ') &&
      t.getAttribute?.('role') === 'button' &&
      t.tagName !== 'BUTTON'
    ) {
      e.preventDefault();
      t.click();
    }
  };

  scr.addEventListener('click', onClick);
  scr.addEventListener('keydown', onKey);
  scr.addEventListener('input', onInput);
  applyFilters();
  syncCartUi();

  return () => {
    clearTimeout(toastTimer);
    scr.removeEventListener('click', onClick);
    scr.removeEventListener('keydown', onKey);
    scr.removeEventListener('input', onInput);
    cleanups.forEach(fn => fn());
    observers.forEach(io => io.disconnect());
    layer.remove();
    scr.classList.remove('ps-lock', 'ps-covered');
    for (const ch of [...scr.children]) ch.removeAttribute('inert');
    cartButtons.forEach(b => b.querySelector('.ps-badge')?.remove());
    delete scr.dataset.psMounted;
  };
}

/** Mounts every phone under `host`; returns one cleanup. */
export function mountPhones(host: ParentNode, opts: MountOptions): () => void {
  const offs = [...host.querySelectorAll<HTMLElement>('.scr')].map(s => mountPhone(s, opts));
  return () => offs.forEach(off => off());
}
